namespace ghidra.app.util.datatype.microsoft;

using ghidra.docking.settings;
using ghidra.program.model.data;
using ghidra.program.model.mem;
using ghidra.util;
using ghidra.util;

public class HTMLResourceDataType : BuiltIn, Dynamic {

	public HTMLResourceDataType() : this(null)
    {
	}

	public HTMLResourceDataType(DataTypeManager dtm) : base(null, "HTML-Resource", dtm)
    {
	}

	/* @Override */
	public DataType clone(DataTypeManager dtm) {
		if (dtm == getDataTypeManager()) {
			return this;
		}
		return new HTMLResourceDataType(dtm);
	}

	/* @Override */
	public string getMnemonic(Settings settings) {
		return "HTML";
	}

	/* @Override */
	public int getLength() {
		return -1;
	}

	/* @Override */
	public int getLength(MemBuffer buf, int maxLength) {
		if (buf != null && maxLength < 0) {
			return maxLength;
		}
		return maxLength;
	}

	/* @Override */
	public string getDescription() {
		return "HTML Resource stored within program";
	}

	/* @Override */
	public object getValue(MemBuffer buf, Settings settings, int length) {
		byte[] data = new byte[length];
		if (buf.getBytes(data, 0) != length) {
			Msg.error(this, "HTML Resource error: Not enough bytes in memory");
			return null;
		}
		string htmlString = new string(data);
		string rawMessage = HTMLUtilities.fromHTML(htmlString);
		return rawMessage;
	}

	/* @Override */
	public Class<object> getValueClass(Settings settings) {
		return typeof(string);
	}

	/* @Override */
	public string getRepresentation(MemBuffer buf, Settings settings, int length) {
		if (length <= 0) {
			return "??";
		}

		string htmlString = (string) getValue(buf, settings, length);
		if (htmlString == null) {
			return "<HTML-Resource>";
		}

		string rawMessage = HTMLUtilities.fromHTML(htmlString);
		// because JDOM doesn't like 0x00's - don't need them just for rendering the ascii
		rawMessage = rawMessage.replaceAll("\0", "");
		return rawMessage;
	}

	/* @Override */
	public bool canSpecifyLength() {
		return true;
	}

	/* @Override */
	public DataType getReplacementBaseType() {
		return ByteDataType.dataType;
	}

}
